27	func newMigrateCmd() *cobra.Command {
28		var checkpointsFlag string
29		var forceFlag bool
30	
31		cmd := &cobra.Command{
32			Use:    "migrate",
33			Short:  "Migrate Entire data to newer formats",
34			Long:   `Migrate Entire data to newer formats. Currently supports migrating v1 checkpoints to v2.`,
35			Hidden: true,
36			RunE: func(cmd *cobra.Command, _ []string) error {
37				if checkpointsFlag == "" {
38					return cmd.Help()
39				}
40				if checkpointsFlag != "v2" {
41					return fmt.Errorf("unsupported checkpoints version: %q (only \"v2\" is supported)", checkpointsFlag)
42				}
43	
44				ctx := cmd.Context()
45	
46				if _, err := paths.WorktreeRoot(ctx); err != nil {
47					cmd.SilenceUsage = true
48					fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
49					return NewSilentError(errors.New("not a git repository"))
50				}
51	
52				logging.SetLogLevelGetter(GetLogLevel)
53				if initErr := logging.Init(ctx, ""); initErr != nil {
54					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not initialize logging: %v\n", initErr)
55				} else {
56					defer logging.Close()
57				}
58				return runMigrateCheckpointsV2(ctx, cmd, forceFlag)
59			},
60		}
61	
62		cmd.Flags().StringVar(&checkpointsFlag, "checkpoints", "", "Target checkpoint format version (e.g., \"v2\")")
63		cmd.Flags().BoolVar(&forceFlag, "force", false, "Force re-migration of all checkpoints, overwriting existing v2 data")
64	
65		return cmd
66	}
