74	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
75		repo, err := strategy.OpenRepository(ctx)
76		if err != nil {
77			cmd.SilenceUsage = true
78			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
79			return NewSilentError(err)
80		}
81	
82		v1Store := checkpoint.NewGitStore(repo)
83		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
84		out := cmd.OutOrStdout()
85	
86		result, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, out, force)
87		if err != nil {
88			return err
89		}
90	
91		fmt.Fprintf(out, "\nMigration complete: %d migrated, %d skipped, %d failed\n",
92			result.migrated, result.skipped, result.failed)
93	
94		if result.failed > 0 {
95			fmt.Fprintf(out, "%d checkpoint(s) failed to migrate. Check .entire/logs/ for details.\n", result.failed)
96			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
97		}
98	
99		return nil
100	}
