243	func repairPartialV2Checkpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (bool, error) {
244		repaired := false
245	
246		// Spot-check already present sessions: ensure required /full/current artifacts exist.
247		existingSessionCount := len(v2Summary.Sessions)
248		for sessionIdx := range existingSessionCount {
249			ok, checkErr := hasCurrentFullSessionArtifacts(repo, v2Store, info.CheckpointID, sessionIdx)
250			if checkErr != nil {
251				return false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
252			}
253			if ok {
254				continue
255			}
256	
257			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
258			if readErr != nil {
259				return false, fmt.Errorf("failed to read v1 session %d while repairing v2: %w", sessionIdx, readErr)
260			}
261	
262			updateOpts := checkpoint.UpdateCommittedOptions{
263				CheckpointID: info.CheckpointID,
264				SessionID:    content.Metadata.SessionID,
265				// content.Transcript was read from v1 checkpoint storage and is
266				// already redacted at write time.
267				Transcript: redact.AlreadyRedacted(content.Transcript),
268				Prompts:    checkpoint.SplitPromptContent(content.Prompts),
269				Agent:      content.Metadata.Agent,
270			}
271			if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
272				updateOpts.CompactTranscript = compacted
273			}
274	
275			if updateErr := v2Store.UpdateCommitted(ctx, updateOpts); updateErr != nil {
276				return false, fmt.Errorf("failed to repair v2 session %d: %w", sessionIdx, updateErr)
277			}
278			repaired = true
279		}
280	
281		return repaired, nil
282	}
