319	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
320	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
321	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
322	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary, out io.Writer, prefix string) error {
323		// Find sessions missing transcript.jsonl
324		var needsBackfill []int
325		for i, session := range v2Summary.Sessions {
326			if session.Transcript == "" {
327				needsBackfill = append(needsBackfill, i)
328			}
329		}
330	
331		if len(needsBackfill) == 0 {
332			return errAlreadyMigrated
333		}
334	
335		backfilled := 0
336		var lastAgent string
337	
338		for _, sessionIdx := range needsBackfill {
339			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
340			if readErr != nil {
341				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
342					slog.String("checkpoint_id", string(info.CheckpointID)),
343					slog.Int("session_index", sessionIdx),
344					slog.String("error", readErr.Error()),
345				)
346				continue
347			}
348	
349			if content.Metadata.Agent != "" {
350				lastAgent = string(content.Metadata.Agent)
351			}
352	
353			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
354			if compacted == nil {
355				// tryCompactTranscript already logs for no-agent and compact-error cases;
356				// log the empty-transcript case here.
357				if len(content.Transcript) == 0 {
358					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
359						slog.String("checkpoint_id", string(info.CheckpointID)),
360						slog.Int("session_index", sessionIdx),
361					)
362				}
363				continue
364			}
365	
366			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
367				CheckpointID:      info.CheckpointID,
368				SessionID:         content.Metadata.SessionID,
369				CompactTranscript: compacted,
370			})
371			if updateErr != nil {
372				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
373					slog.String("checkpoint_id", string(info.CheckpointID)),
374					slog.Int("session_index", sessionIdx),
375					slog.String("error", updateErr.Error()),
376				)
377				continue
378			}
379	
380			backfilled++
381		}
382	
383		if backfilled == 0 {
384			if lastAgent != "" {
385				return fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
386			}
387			return fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
388		}
389	
390		fmt.Fprintf(out, "%s added transcript.jsonl for %d session(s)\n", prefix, backfilled)
391	
392		return nil
393	}
