552	// resolveV1CheckpointTree reads the checkpoint subtree from the v1 branch.
553	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
554		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
555		ref, err := repo.Reference(refName, true)
556		if err != nil {
557			// Try remote tracking branch
558			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
559			ref, err = repo.Reference(remoteRefName, true)
560			if err != nil {
561				return nil, fmt.Errorf("v1 branch not found: %w", err)
562			}
563		}
564	
565		commit, err := repo.CommitObject(ref.Hash())
566		if err != nil {
567			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
568		}
569	
570		rootTree, err := commit.Tree()
571		if err != nil {
572			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
573		}
574	
575		cpTree, err := rootTree.Tree(cpID.Path())
576		if err != nil {
577			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
578		}
579	
580		return cpTree, nil
581	}
